content.text:
Brief:
Un labyrinthe de haies vu du dessus, joué au tour par tour. Le joueur guide un hérisson case par case en glissant le doigt vers une direction. Chaque déplacement coûte un pas, et des pommes posées dans les allées rapportent des points. La partie est gagnée quand le hérisson atteint la sortie, et elle est bloquée si plus aucun pas ne reste. Aucun chronomètre ne presse le joueur.

Plan:
{"gameType":"puzzle-board","input":"swipe-lanes","lang":"fr","loop":"Glissez le doigt pour guider le hérisson case par case dans le labyrinthe et ramasser des pommes. Chaque pas compte : atteignez la sortie avant d'épuiser vos pas, sinon la partie est bloquée.","slug":"le-herisson-des-haies","style":"paper-cut","title":"Le Hérisson des Haies"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Hérisson des Haies</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     overflow: hidden;
11|     background: #f4ecd8;
12|     font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
13|     touch-action: none;
14|   }
15|   #wrap {
16|     position: fixed; inset: 0;
17|     display: flex; align-items: center; justify-content: center;
18|   }
19|   canvas {
20|     display: block;
21|     touch-action: none;
22|   }
23| </style>
24| </head>
25| <body>
26| <div id="wrap">
27| <canvas id="game"></canvas>
28| </div>
29| <script>
30| // ---- Bridge helper (verbatim) ----
31| const CARTRIDGE = {
32|   send(type, payload = {}) {
33|     window.parent.postMessage(
34|       { source: "cartridge", v: 1, type, payload },
35|       "*",
36|     );
37|   },
38| };
39| 
40| window.addEventListener("message", (event) => {
41|   const data = event.data;
42|   if (!data || data.source !== "cartridge-host") return;
43|   if (data.type === "pause") paused = true;
44|   if (data.type === "resume") paused = false;
45|   if (data.type === "reset") backToTitle();
46| });
47| 
48| // ---- Game setup ----
49| const canvas = document.getElementById("game");
50| const ctx = canvas.getContext("2d");
51| 
52| let DPR = Math.max(1, window.devicePixelRatio || 1);
53| let CW = 0, CH = 0; // CSS pixel size
54| 
55| let paused = false;
56| let started = false;
57| 
58| // Palette
59| const COL_BG = "#f4ecd8";
60| const COL_LAYER = "#e07a5f";
61| const COL_ACCENT = "#3d405b";
62| const COL_HILITE = "#81b29a";
63| 
64| // --- Seeded jitter for paper-cut look ---
65| function makeRng(seed) {
66|   let s = seed >>> 0;
67|   return function () {
68|     s = (s * 1664525 + 1013904223) >>> 0;
69|     return s / 4294967296;
70|   };
71| }
72| const jitterRng = makeRng(20240501);
73| function jitterVal(scale) {
74|   return (jitterRng() - 0.5) * 2 * scale;
75| }
76| 
77| // --- Maze definition ---
78| // Grid based maze. 0 = hedge wall, 1 = path, 2 = apple, 3 = start, 4 = exit
79| const GRID_W = 9;
80| const GRID_H = 11;
81| 
82| // Simple hand-authored maze (hedge=1 wall represented by border char, we'll build with algorithm below instead)
83| let grid = [];
84| let stepsLeft = 0;
85| let maxSteps = 0;
86| let applesTotal = 0;
87| let applesCollected = 0;
88| let hedgehog = { x: 0, y: 0 };
89| let exitPos = { x: 0, y: 0 };
90| let score = 0;
91| let stage = 1;
92| let gameOver = false; // true after end sent
93| let endReason = null;
94| 
95| function buildMaze(seed) {
96|   const rng = makeRng(seed);
97|   // start all walls
98|   const w = GRID_W, h = GRID_H;
99|   const cells = [];
100|   for (let y = 0; y < h; y++) {
101|     cells.push(new Array(w).fill(0));
102|   }
103|   // carve using randomized DFS on odd coordinates
104|   function idx(x, y) { return y * w + x; }
105|   const visited = new Array(w * h).fill(false);
106|   function inBounds(x, y) { return x >= 0 && x < w && y >= 0 && y < h; }
107|   const stack = [];
108|   let startX = 1, startY = 1;
109|   cells[startY][startX] = 1;
110|   visited[idx(startX, startY)] = true;
111|   stack.push([startX, startY]);
112|   const dirs = [[2,0],[-2,0],[0,2],[0,-2]];
113|   while (stack.length) {
114|     const [cx, cy] = stack[stack.length - 1];
115|     // shuffle dirs
116|     const dd = dirs.slice();
117|     for (let i = dd.length - 1; i > 0; i--) {
118|       const j = Math.floor(rng() * (i + 1));
119|       [dd[i], dd[j]] = [dd[j], dd[i]];
120|     }
121|     let carved = false;
122|     for (const [dx, dy] of dd) {
123|       const nx = cx + dx, ny = cy + dy;
124|       if (inBounds(nx, ny) && !visited[idx(nx, ny)]) {
125|         cells[cy + dy / 2][cx + dx / 2] = 1;
126|         cells[ny][nx] = 1;
127|         visited[idx(nx, ny)] = true;
128|         stack.push([nx, ny]);
129|         carved = true;
130|         break;
131|       }
132|     }
133|     if (!carved) stack.pop();
134|   }
135|   return cells;
136| }
137| 
138| function collectPathCells(cells) {
139|   const list = [];
140|   for (let y = 0; y < GRID_H; y++) {
141|     for (let x = 0; x < GRID_W; x++) {
142|       if (cells[y][x] === 1) list.push({ x, y });
143|     }
144|   }
145|   return list;
146| }
147| 
148| function manhattan(a, b) {
149|   return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
150| }
151| 
152| function setupLevel(levelIndex) {
153|   grid = buildMaze(1000 + levelIndex * 77);
154|   const pathCells = collectPathCells(grid);
155|   // start at 1,1
156|   hedgehog = { x: 1, y: 1 };
157|   // pick exit as farthest reachable path cell
158|   let best = pathCells[0];
159|   let bestDist = -1;
160|   for (const c of pathCells) {
161|     const d = manhattan(c, hedgehog);
162|     if (d > bestDist) { bestDist = d; best = c; }
163|   }
164|   exitPos = { x: best.x, y: best.y };
165|   grid[hedgehog.y][hedgehog.x] = 3;
166|   grid[exitPos.y][exitPos.x] = 4;
167| 
168|   // place apples on some path cells (not start/exit)
169|   const candidates = pathCells.filter(c =>
170|     !(c.x === hedgehog.x && c.y === hedgehog.y) &&
171|     !(c.x === exitPos.x && c.y === exitPos.y)
172|   );
173|   const rng = makeRng(555 + levelIndex * 31);
174|   for (let i = candidates.length - 1; i > 0; i--) {
175|     const j = Math.floor(rng() * (i + 1));
176|     [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
177|   }
178|   const appleCount = Math.min(6, Math.floor(candidates.length * 0.18) + 3);
179|   applesTotal = 0;
180|   for (let i = 0; i < appleCount && i < candidates.length; i++) {
181|     const c = candidates[i];
182|     grid[c.y][c.x] = 2;
183|     applesTotal++;
184|   }
185|   applesCollected = 0;
186| 
187|   // steps budget: shortest path length * factor + apples reach margin
188|   maxSteps = Math.floor(bestDist * 2.2) + applesTotal * 3 + 6;
189|   stepsLeft = maxSteps;
190|   gameOver = false;
191|   endReason = null;
192| }
193| 
194| // --- Layout ---
195| let cellSize = 20;
196| let boardOffsetX = 0, boardOffsetY = 0;
197| let topBarHeight = 70;
198| 
199| function resize() {
200|   CW = window.innerWidth;
201|   CH = window.innerHeight;
202|   DPR = Math.max(1, window.devicePixelRatio || 1);
203|   canvas.width = Math.floor(CW * DPR);
204|   canvas.height = Math.floor(CH * DPR);
205|   canvas.style.width = CW + "px";
206|   canvas.style.height = CH + "px";
207|   ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
208| 
209|   const availH = CH - topBarHeight - 20;
210|   const availW = CW - 20;
211|   cellSize = Math.floor(Math.min(availW / GRID_W, availH / GRID_H));
212|   cellSize = Math.max(cellSize, 16);
213|   boardOffsetX = (CW - GRID_W * cellSize) / 2;
214|   boardOffsetY = topBarHeight + (availH - GRID_H * cellSize) / 2;
215|   draw();
216| }
217| window.addEventListener("resize", resize);
218| 
219| // --- Drawing helpers: paper-cut style ---
220| function roundRectPath(x, y, w, h, r) {
221|   ctx.beginPath();
222|   ctx.moveTo(x + r, y);
223|   ctx.arcTo(x + w, y, x + w, y + h, r);
224|   ctx.arcTo(x + w, y + h, x, y + h, r);
225|   ctx.arcTo(x, y + h, x, y, r);
226|   ctx.arcTo(x, y, x + w, y, r);
227|   ctx.closePath();
228| }
229| 
230| function jitteredRoundRect(x, y, w, h, r, seedOffset) {
231|   // Draw a slightly irregular quad using jitter on corners for paper-cut edges
232|   const j = 1.5;
233|   ctx.beginPath();
234|   const pts = [
235|     [x, y], [x + w, y], [x + w, y + h], [x, y + h]
236|   ];
237|   const jp = pts.map((p, i) => [
238|     p[0] + jitterVal(j),
239|     p[1] + jitterVal(j)
240|   ]);
241|   ctx.moveTo(jp[0][0] + r, jp[0][1]);
242|   ctx.lineTo(jp[1][0] - r, jp[1][1]);
243|   ctx.quadraticCurveTo(jp[1][0], jp[1][1], jp[1][0], jp[1][1] + r);
244|   ctx.lineTo(jp[2][0], jp[2][1] - r);
245|   ctx.quadraticCurveTo(jp[2][0], jp[2][1], jp[2][0] - r, jp[2][1]);
246|   ctx.lineTo(jp[3][0] + r, jp[3][1]);
247|   ctx.quadraticCurveTo(jp[3][0], jp[3][1], jp[3][0], jp[3][1] - r);
248|   ctx.lineTo(jp[0][0], jp[0][1] + r);
249|   ctx.quadraticCurveTo(jp[0][0], jp[0][1], jp[0][0] + r, jp[0][1]);
250|   ctx.closePath();
251| }
252| 
253| function drawShadowLayer(drawFn) {
254|   ctx.save();
255|   ctx.shadowColor = "rgba(61,64,91,0.35)";
256|   ctx.shadowBlur = 6;
257|   ctx.shadowOffsetY = 3;
258|   drawFn();
259|   ctx.restore();
260| }
261| 
262| function drawBackground() {
263|   ctx.fillStyle = COL_BG;
264|   ctx.fillRect(0, 0, CW, CH);
265| }
266| 
267| function drawTopBar() {
268|   const plateW = CW - 20;
269|   const plateH = 56;
270|   const px = 10, py = 8;
271|   drawShadowLayer(() => {
272|     ctx.fillStyle = COL_LAYER;
273|     jitteredRoundRect(px, py, plateW, plateH, 10);
274|     ctx.fill();
275|   });
276|   ctx.fillStyle = "#fff8ec";
277|   ctx.font = "bold 16px sans-serif";
278|   ctx.textBaseline = "middle";
279|   ctx.textAlign = "left";
280|   ctx.fillText("Score: " + score, px + 16, py + plateH / 2);
281| 
282|   ctx.textAlign = "center";
283|   ctx.fillText("🦔 " + applesCollected + "/" + applesTotal, px + plateW / 2, py + plateH / 2);
284| 
285|   ctx.textAlign = "right";
286|   ctx.fillStyle = stepsLeft <= 3 ? "#ffd7d0" : "#fff8ec";
287|   ctx.fillText("Pas: " + stepsLeft, px + plateW - 16, py + plateH / 2);
288| }
289| 
290| function cellRect(gx, gy) {
291|   return {
292|     x: boardOffsetX + gx * cellSize,
293|     y: boardOffsetY + gy * cellSize,
294|     w: cellSize,
295|     h: cellSize
296|   };
297| }
298| 
299| function drawBoardBase() {
300|   // board backing plate
301|   const bx = boardOffsetX - 8;
302|   const by = boardOffsetY - 8;
303|   const bw = GRID_W * cellSize + 16;
304|   const bh = GRID_H * cellSize + 16;
305|   drawShadowLayer(() => {
306|     ctx.fillStyle = "#fffaf0";
307|     jitteredRoundRect(bx, by, bw, bh, 14);
308|     ctx.fill();
309|   });
310| }
311| 
312| function drawHedges() {
313|   for (let y = 0; y < GRID_H; y++) {
314|     for (let x = 0; x < GRID_W; x++) {
315|       if (grid[y][x] === 0) {
316|         const r = cellRect(x, y);
317|         drawShadowLayer(() => {
318|           ctx.fillStyle = COL_HILITE;
319|           jitteredRoundRect(r.x + 1, r.y + 1, r.w - 2, r.h - 2, 4);
320|           ctx.fill();
321|         });
322|         // little leaf texture lines
323|         ctx.strokeStyle = "rgba(61,64,91,0.25)";
324|         ctx.lineWidth = 1;
325|         ctx.beginPath();
326|         ctx.moveTo(r.x + 3, r.y + r.h * 0.4);
327|         ctx.lineTo(r.x + r.w - 3, r.y + r.h * 0.6);
328|         ctx.stroke();
329|       }
330|     }
331|   }
332| }
333| 
334| function drawApples() {
335|   for (let y = 0; y < GRID_H; y++) {
336|     for (let x = 0; x < GRID_W; x++) {
337|       if (grid[y][x] === 2) {
338|         const r = cellRect(x, y);
339|         const cx = r.x + r.w / 2;
340|         const cy = r.y + r.h / 2;
341|         const rad = cellSize * 0.24;
342|         drawShadowLayer(() => {
343|           ctx.fillStyle = COL_LAYER;
344|           ctx.beginPath();
345|           ctx.arc(cx + jitterVal(1), cy + jitterVal(1), rad, 0, Math.PI * 2);
346|           ctx.fill();
347|         });
348|         ctx.fillStyle = COL_ACCENT;
349|         ctx.fillRect(cx - 1, cy - rad - 4, 2, 4);
350|       }
351|     }
352|   }
353| }
354| 
355| function drawExit() {
356|   const r = cellRect(exitPos.x, exitPos.y);
357|   drawShadowLayer(() => {
358|     ctx.fillStyle = COL_ACCENT;
359|     jitteredRoundRect(r.x + 3, r.y + 3, r.w - 6, r.h - 6, 6);
360|     ctx.fill();
361|   });
362|   ctx.fillStyle = COL_HILITE;
363|   ctx.font = (cellSize * 0.5) + "px sans-serif";
364|   ctx.textAlign = "center";
365|   ctx.textBaseline = "middle";
366|   ctx.fillText("🚪", r.x + r.w / 2, r.y + r.h / 2 + 1);
367| }
368| 
369| function drawHedgehog() {
370|   const r = cellRect(hedgehog.x, hedgehog.y);
371|   const cx = r.x + r.w / 2;
372|   const cy = r.y + r.h / 2;
373|   drawShadowLayer(() => {
374|     ctx.fillStyle = COL_ACCENT;
375|     ctx.beginPath();
376|     ctx.arc(cx, cy, cellSize * 0.32, 0, Math.PI * 2);
377|     ctx.fill();
378|   });
379|   ctx.font = (cellSize * 0.55) + "px sans-serif";
380|   ctx.textAlign = "center";
381|   ctx.textBaseline = "middle";
382|   ctx.fillText("🦔", cx, cy + 1);
383| }
384| 
385| function drawOverlayMessage(lines, sub) {
386|   ctx.save();
387|   ctx.fillStyle = "rgba(61,64,91,0.55)";
388|   ctx.fillRect(0, 0, CW, CH);
389|   const plateW = Math.min(CW - 40, 420);
390|   const plateH = 200;
391|   const px = (CW - plateW) / 2;
392|   const py = (CH - plateH) / 2;
393|   drawShadowLayer(() => {
394|     ctx.fillStyle = "#fff8ec";
395|     jitteredRoundRect(px, py, plateW, plateH, 16);
396|     ctx.fill();
397|   });
398|   ctx.fillStyle = COL_ACCENT;
399|   ctx.textAlign = "center";
400|   ctx.textBaseline = "middle";
401|   ctx.font = "bold 22px sans-serif";
402|   ctx.fillText(lines, CW / 2, py + plateH * 0.4);
403|   ctx.font = "16px sans-serif";
404|   ctx.fillText(sub, CW / 2, py + plateH * 0.65);
405|   ctx.restore();
406| }
407| 
408| function draw() {
409|   drawBackground();
410|   drawTopBar();
411|   drawBoardBase();
412|   drawHedges();
413|   drawApples();
414|   drawExit();
415|   drawHedgehog();
416| 
417|   if (!started) {
418|     drawOverlayMessage("Le Hérisson des Haies", "Glissez pour vous déplacer et ramasser les pommes");
419|   } else if (gameOver) {
420|     if (endReason === "win") {
421|       drawOverlayMessage("Bravo, vous êtes sorti(e) !", "Glissez pour rejouer");
422|     } else if (endReason === "stuck") {
423|       drawOverlayMessage("Plus de pas...", "Glissez pour réessayer");
424|     }
425|   } else if (paused) {
426|     drawOverlayMessage("Pause", "En attente...");
427|   }
428| }
429| 
430| // --- Game logic ---
431| function isWalkable(x, y) {
432|   if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return false;
433|   return grid[y][x] !== 0;
434| }
435| 
436| function anyLegalMove() {
437|   if (stepsLeft <= 0) return false;
438|   const { x, y } = hedgehog;
439|   return isWalkable(x + 1, y) || isWalkable(x - 1, y) || isWalkable(x, y + 1) || isWalkable(x, y - 1);
440| }
441| 
442| function tryMove(dx, dy) {
443|   if (!started || gameOver || paused) return;
444|   const nx = hedgehog.x + dx;
445|   const ny = hedgehog.y + dy;
446|   if (!isWalkable(nx, ny)) return;
447|   if (stepsLeft <= 0) return;
448| 
449|   hedgehog.x = nx;
450|   hedgehog.y = ny;
451|   stepsLeft -= 1;
452| 
453|   let scored = false;
454|   if (grid[ny][nx] === 2) {
455|     grid[ny][nx] = 1;
456|     applesCollected += 1;
457|     score += 10;
458|     scored = true;
459|   }
460| 
461|   if (nx === exitPos.x && ny === exitPos.y) {
462|     score += 50 + stepsLeft * 2;
463|     scored = true;
464|   }
465| 
466|   if (scored) {
467|     CARTRIDGE.send("score", { value: score });
468|   }
469| 
470|   if (nx === exitPos.x && ny === exitPos.y) {
471|     gameOver = true;
472|     endReason = "win";
473|     CARTRIDGE.send("end", { reason: "win", value: score });
474|   } else if (!anyLegalMove()) {
475|     gameOver = true;
476|     endReason = "stuck";
477|     CARTRIDGE.send("end", { reason: "stuck" });
478|   }
479| 
480|   draw();
481| }
482| 
483| // --- Input: swipe lanes style, adapted to 4-direction grid ---
484| const SWIPE_FRACTION = 0.08;
485| let pressX = 0, pressY = 0;
486| let pressActive = false;
487| 
488| function beginPlay() {
489|   if (started && !gameOver) return;
490|   started = true;
491|   gameOver = false;
492|   endReason = null;
493|   score = 0;
494|   stage = 1;
495|   setupLevel(stage);
496|   CARTRIDGE.send("start");
497|   CARTRIDGE.send("level", { index: stage });
498|   CARTRIDGE.send("score", { value: score });
499|   draw();
500| }
501| 
502| function nextStage() {
503|   stage += 1;
504|   setupLevel(stage);
505|   CARTRIDGE.send("level", { index: stage });
506|   draw();
507| }
508| 
509| canvas.addEventListener("pointerdown", (event) => {
510|   pressX = event.clientX;
511|   pressY = event.clientY;
512|   pressActive = true;
513| });
514| 
515| canvas.addEventListener("pointerup", (event) => {
516|   if (!pressActive) return;
517|   pressActive = false;
518| 
519|   if (!started || gameOver) {
520|     if (gameOver && endReason === "win") {
521|       nextStage();
522|       // still "started", not gameOver until nextStage resolves
523|       started = true;
524|       gameOver = false;
525|       draw();
526|       return;
527|     }
528|     beginPlay();
529|     return;
530|   }
531| 
532|   const dx = event.clientX - pressX;
533|   const dy = event.clientY - pressY;
534|   const w = canvas.clientWidth;
535|   const h = canvas.clientHeight;
536| 
537|   const minSwipe = w * SWIPE_FRACTION;
538|   const minSwipeV = h * SWIPE_FRACTION;
539| 
540|   if (Math.abs(dx) < minSwipe && Math.abs(dy) < minSwipeV) return;
541| 
542|   if (Math.abs(dx) >= Math.abs(dy)) {
543|     if (Math.abs(dx) >= minSwipe) {
544|       tryMove(Math.sign(dx), 0);
545|     }
546|   } else {
547|     if (Math.abs(dy) >= minSwipeV) {
548|       tryMove(0, Math.sign(dy));
549|     }
550|   }
551| });
552| 
553| window.addEventListener("keydown", (event) => {
554|   if (!started || gameOver) {
555|     if (event.key === "Enter" || event.key === " ") {
556|       beginPlay();
557|     }
558|     return;
559|   }
560|   if (event.key === "ArrowLeft") tryMove(-1, 0);
561|   else if (event.key === "ArrowRight") tryMove(1, 0);
562|   else if (event.key === "ArrowUp") tryMove(0, -1);
563|   else if (event.key === "ArrowDown") tryMove(0, 1);
564| });
565| 
566| function backToTitle() {
567|   started = false;
568|   gameOver = false;
569|   endReason = null;
570|   paused = false;
571|   draw();
572| }
573| 
574| // --- Pause/resume loop guard (redraw driven by input, but keep a light rAF for overlay consistency) ---
575| let rafId = null;
576| function loop() {
577|   if (!paused) {
578|     draw();
579|   }
580|   rafId = requestAnimationFrame(loop);
581| }
582| 
583| // --- Boot ---
584| function init() {
585|   resize();
586|   // draw first frame before boot event
587|   draw();
588|   CARTRIDGE.send("boot", { title: "Le Hérisson des Haies", gameType: "puzzle-board", lang: "fr" });
589|   requestAnimationFrame(loop);
590| }
591| 
592| init();
593| </script>
594| </body>
595| </html>
596|

